// Where the site lives. Pages can be served from a sub-path (a GitHub
// Pages project site is https://user.github.io/repo/), so the links
// can't be hard-coded as "/models.html": that would point at the
// domain root.
//
// - dev:   the dev server root.
// - build: Vite emits scripts into <site>/assets/, so one level up from
//          this module is the site root, whichever page (or folder) the
//          header is on.
const siteRoot = import.meta.env.DEV
    ? new URL('/', location.origin)
    : new URL('../', import.meta.url);

// Page files, relative to the site root
const LINKS = [
    { file: 'index.html', label: 'Home' },
    { file: 'models.html', label: '3D Models' },
    { file: 'animations.html', label: 'Animations' },
    { file: 'communicationsCourses.html', label: 'Communications Courses' },
    { file: 'computerScienceCourses.html', label: 'Computer Science Courses' },
];

// Compare pages regardless of how they were reached:
// "/repo/", "/repo/index.html"  -> "/repo"
// "/repo/models.html", "/repo/models" -> "/repo/models"
const normalize = (path: string): string =>
    path.replace(/(index)?\.html$/, '').replace(/\/$/, '');

class AppHeader extends HTMLElement {
    connectedCallback() {
        const current = normalize(window.location.pathname);

        const buttons = LINKS.map(({ file, label }) => {
            const url = new URL(file, siteRoot);
            const active = normalize(url.pathname) === current;

            return `
            <button data-href="${url.href}" class="${active ? 'active' : ''}">
              ${label}
            </button>`;
        }).join('');

        this.innerHTML = `
      <header class="site-header">
        <div class="header-inner">
          <div class="brand">
            <span class="brand-icon"></span>
            <span class="brand-name">Middleton Henry</span>
          </div>


          <nav class="nav-links">
            ${buttons}
          </nav>
        </div>
      </header>
    `;

        this.querySelectorAll('button').forEach((btn) => {
            btn.addEventListener('click', () => {
                const target = btn.getAttribute('data-href');
                if (target) window.location.href = target;
            });
        });
    }
}

// Guard against defining twice (hot reload)
if (!customElements.get('app-header')) {
    customElements.define('app-header', AppHeader);
}